<?php
namespace App\Services;
use App\Models\Automation;use App\Models\Device;use App\Models\DeviceAccessAssignment;use App\Models\ResourceRevision;use App\Models\User;use Illuminate\Validation\ValidationException;
final class AutomationPublicationValidator{public function validate(Automation $a,ResourceRevision $r,?User $submitter=null):void{$s=$r->snapshot;if($r->resource_type!=='automation'||(int)$r->resource_id!==(int)$a->id)$this->fail('revision_id','Revision does not belong to this Automation.');if(!in_array(data_get($s,'trigger.type'),['telemetry','device_status','schedule','manual'],true))$this->fail('trigger','Trigger type is not publication-safe.');foreach($s['actions']??[] as $action)if(($action['type']??null)!=='notification')$this->fail('actions','Action type is not publication-safe.');$id=data_get($s,'trigger.deviceId');if($id!==null){$device=Device::where(['id'=>$id,'organization_id'=>$a->organization_id])->first();if(!$device)$this->fail('trigger.deviceId','Target Device is missing or outside the Automation organization.');if($submitter&&!$submitter->isPlatformAdmin()&&!DeviceAccessAssignment::where(['device_id'=>$id,'user_id'=>$submitter->id,'access_level'=>'full_access'])->exists())$this->fail('trigger.deviceId','Submitter no longer has Full Access to the target Device.');}$this->secrets($s);}private function secrets(array $v):void{foreach($v as $k=>$x){if(preg_match('/^(authorization|password|secret|credential|access_token|refresh_token|api_key|private_key|cookie)$/i',(string)$k))$this->fail('revision','Publication cannot contain secrets.');if(is_array($x))$this->secrets($x);}}private function fail(string $f,string $m):never{throw ValidationException::withMessages([$f=>[$m]]);}}
